#!/bin/bash

#concatenates the solution output files generated by unsteady_density 
for RDIR in DISPERSION_RESULT{2..2}; do
	FILES=${RDIR}/soln_density*_on_proc0.dat
	RDIR_OUT=COMBINED_${RDIR}
	mkdir ${RDIR_OUT}
	cp ${RDIR}/params.dat ${RDIR_OUT}
	cp ${RDIR}/t_out.dat ${RDIR_OUT}
	COUNT=0
	i=0
	for f in $FILES; do
		i=$(echo ${f} | egrep -o 'density[0-9]{1,5}' | egrep -o '[0-9]{1,5}')
		#echo ${RDIR}/soln_density${i}_on_proc*
		#echo ${RDIR}/soln_helm${i}_on_proc* 
		{
		cat ${RDIR}/soln_density${i}_on_proc{0..74}.dat > ${RDIR_OUT}/soln_density${i}.dat
		cat ${RDIR}/soln_helm${i}_on_proc{0..74}.dat > ${RDIR_OUT}/soln_helm${i}.dat
		} &> /dev/null
		COUNT=$((COUNT+1))
	done
	#cp ${RDIR_OUT}/soln_helm$((i)).dat ${RDIR_OUT}/soln_helmss.dat
	#cp ${RDIR_OUT}/soln_density$((i)).dat ${RDIR_OUT}/soln_densityss.dat
done
